/* ══════════════════════════════════════════════════════════════════
   实验 2 · Raft 选举模拟器（真的在跑状态机 + 消息传递）
   ══════════════════════════════════════════════════════════════════ */
const NN=5, MAJ=Math.floor(NN/2)+1, HB=150;
const R={nodes:[],msgs:[],run:false,last:0,part:false,
  elections:0,splits:0,maxLeadersPerTerm:1,violated:false,log:[]};
const P2X=[], P2Y=[];
(function layout(){
  const cx=360, cy=150, rad=112;
  for(let i=0;i<NN;i++){ const a=-Math.PI/2+i*2*Math.PI/NN;
    P2X.push(cx+rad*Math.cos(a)); P2Y.push(cy+rad*Math.sin(a)); }
})();
function cfg2(){return {delay:+$("#r2d").value, loss:+$("#r2l").value/100,
  base:+$("#r2t").value, rand:$("#c2r").checked};}
function rto(){ const c=cfg2(); return c.base + (c.rand? Math.random()*400 : 0); }
function log2(m,col){ R.log.push({m,col}); if(R.log.length>200) R.log.shift(); }
function reset2(){
  R.nodes=[]; R.msgs=[]; R.part=false; R.elections=0; R.splits=0;
  R.maxLeadersPerTerm=1; R.violated=false; R.log=[];
  for(let i=0;i<NN;i++) R.nodes.push({id:i,alive:true,state:"F",term:0,votedFor:null,
    votes:new Set(),timer:0,timeout:rto(),hb:0,grp:i<3?0:1});
  log2("集群启动，5 个节点全部是 Follower");
}
function send(from,to,type,payload){
  const c=cfg2();
  if(R.part && R.nodes[from].grp!==R.nodes[to].grp) return;   // 分区：跨组消息直接丢弃
  const lost=Math.random()<c.loss;
  R.msgs.push({from,to,type,...payload,t:0,dur:c.delay*(0.7+Math.random()*0.6),lost,
    lossAt:0.3+Math.random()*0.4});
}
function stepDown(n,term){ n.term=term; n.state="F"; n.votedFor=null; n.votes.clear(); n.timer=0; n.timeout=rto(); }
function startElection(n){
  n.term++; n.state="C"; n.votedFor=n.id; n.votes=new Set([n.id]);
  n.timer=0; n.timeout=rto(); R.elections++;
  log2("N"+(n.id+1)+" 选举超时 → 成为 Candidate，term="+n.term,"--warn");
  for(let j=0;j<NN;j++) if(j!==n.id) send(n.id,j,"RV",{term:n.term});
}
function becomeLeader(n){
  n.state="L"; n.hb=1e9;
  log2("★ N"+(n.id+1)+" 当选 Leader（term="+n.term+"，得票 "+n.votes.size+"/"+NN+"）","--ok");
}
function deliver(m){
  const to=R.nodes[m.to], from=R.nodes[m.from];
  if(!to.alive) return;
  if(m.type==="RV"){
    if(m.term>to.term) stepDown(to,m.term);
    const grant = m.term===to.term && (to.votedFor===null||to.votedFor===m.from) && to.state!=="L";
    if(grant){ to.votedFor=m.from; to.timer=0; to.timeout=rto(); }
    send(m.to,m.from,"RVR",{term:to.term,granted:grant});
  } else if(m.type==="RVR"){
    if(m.term>to.term){ stepDown(to,m.term); return; }
    if(to.state==="C" && m.granted && m.term===to.term){
      to.votes.add(m.from);
      if(to.votes.size>=MAJ) becomeLeader(to);
    }
  } else if(m.type==="AE"){          // 心跳
    if(m.term>=to.term){
      const wasL = to.state==="L";
      to.term=m.term; to.state="F"; to.votedFor=m.from; to.timer=0; to.timeout=rto(); to.votes.clear();
      if(wasL) log2("N"+(to.id+1)+" 看到 term="+m.term+" 的 Leader，立刻退位","--crit");
    }
  }
}
function tick2(dt){
  // 选举计时器
  for(const n of R.nodes){
    if(!n.alive) continue;
    if(n.state==="L"){
      n.hb+=dt;
      if(n.hb>=HB){ n.hb=0; for(let j=0;j<NN;j++) if(j!==n.id) send(n.id,j,"AE",{term:n.term}); }
    } else {
      n.timer+=dt;
      if(n.timer>=n.timeout){
        if(n.state==="C"){ R.splits++; log2("N"+(n.id+1)+" 选举超时仍未过半 → 分裂投票，重新发起","--crit"); }
        startElection(n);
      }
    }
  }
  // 消息飞行
  for(let i=R.msgs.length-1;i>=0;i--){
    const m=R.msgs[i]; m.t+=dt;
    const pr=m.t/m.dur;
    if(m.lost&&pr>=m.lossAt){ R.msgs.splice(i,1); continue; }
    if(pr>=1){ R.msgs.splice(i,1); deliver(m); }
  }
  // 安全性断言：同一 term 至多一个 leader
  const byTerm={};
  for(const n of R.nodes) if(n.alive&&n.state==="L") byTerm[n.term]=(byTerm[n.term]||0)+1;
  for(const t in byTerm){
    if(byTerm[t]>R.maxLeadersPerTerm) R.maxLeadersPerTerm=byTerm[t];
    if(byTerm[t]>1&&!R.violated){ R.violated=true; log2("⚠ 安全性被破坏：term "+t+" 出现了 "+byTerm[t]+" 个 Leader！","--crit"); }
  }
}
function draw2(){
  const svg=$("#sv2"); svg.innerHTML="";
  // 分区线
  if(R.part){
    const mx1=(P2X[4]+P2X[0])/2, my1=(P2Y[4]+P2Y[0])/2, mx2=(P2X[2]+P2X[3])/2, my2=(P2Y[2]+P2Y[3])/2;
    const dx=mx2-mx1, dy=my2-my1, L=Math.hypot(dx,dy), ex=dx/L*180, ey=dy/L*180;
    svg.appendChild(el("line",{x1:mx1-ex*0.6,y1:my1-ey*0.6,x2:mx2+ex*0.6,y2:my2+ey*0.6,
      stroke:cv("--crit"),"stroke-width":2.5,"stroke-dasharray":"8 6"}));
    svg.appendChild(el("text",{x:mx1-ex*0.6-6,y:my1-ey*0.6-8,fill:cv("--crit"),"font-size":11,
      "text-anchor":"middle","font-family":cv("--sans")},"网络分区"));
  }
  // 连线
  for(let i=0;i<NN;i++) for(let j=i+1;j<NN;j++){
    const cut = R.part && R.nodes[i].grp!==R.nodes[j].grp;
    if(cut) continue;
    svg.appendChild(el("line",{x1:P2X[i],y1:P2Y[i],x2:P2X[j],y2:P2Y[j],
      stroke:cv("--grid"),"stroke-width":1,opacity:.5}));
  }
  // 消息
  R.msgs.forEach(m=>{
    const pr=Math.min(m.t/m.dur,1);
    const x=P2X[m.from]+(P2X[m.to]-P2X[m.from])*pr, y=P2Y[m.from]+(P2Y[m.to]-P2Y[m.from])*pr;
    const dying=m.lost&&pr>m.lossAt-0.1;
    const col = dying?"--serious" : m.type==="AE"?"--s3" : m.type==="RV"?"--s1":"--s4";
    svg.appendChild(el("circle",{cx:x,cy:y,r:dying?6:4.5,fill:cv(col),opacity:dying?.6:1}));
  });
  // 节点
  const ROLE={F:["Follower","--s1"],C:["Candidate","--warn"],L:["Leader","--ok"]};
  R.nodes.forEach((n,i)=>{
    const x=P2X[i], y=P2Y[i];
    const col = n.alive? cv(ROLE[n.state][1]) : cv("--crit");
    if(n.alive&&n.state!=="L"){    // 计时器环
      const p=Math.min(n.timer/n.timeout,1), a=-Math.PI/2+p*2*Math.PI;
      const lg=p>0.5?1:0;
      svg.appendChild(el("path",{d:"M "+x+" "+(y-30)+" A 30 30 0 "+lg+" 1 "+(x+30*Math.cos(a))+" "+(y+30*Math.sin(a)),
        fill:"none",stroke:cv(p>0.8?"--warn":"--ink-3"),"stroke-width":3,opacity:.85}));
    }
    svg.appendChild(el("circle",{cx:x,cy:y,r:24,fill:cv("--surface"),stroke:col,"stroke-width":n.state==="L"?3:2,
      style:"cursor:pointer",class:"nd","data-i":i}));
    svg.appendChild(el("text",{x:x,y:y-2,fill:n.alive?cv("--ink"):cv("--crit"),"font-size":12,"font-weight":700,
      "text-anchor":"middle","font-family":cv("--sans"),style:"pointer-events:none"},n.alive?"N"+(i+1):"☠"));
    svg.appendChild(el("text",{x:x,y:y+12,fill:cv("--ink-3"),"font-size":10,"text-anchor":"middle",
      "font-family":cv("--mono"),style:"pointer-events:none"},"t"+n.term));
    if(n.alive) svg.appendChild(el("text",{x:x,y:y+45,fill:col,"font-size":10.5,"font-weight":650,
      "text-anchor":"middle","font-family":cv("--sans"),style:"pointer-events:none"},ROLE[n.state][0]));
    if(n.state==="C"&&n.alive) svg.appendChild(el("text",{x:x,y:y+58,fill:cv("--ink-3"),"font-size":9.5,
      "text-anchor":"middle","font-family":cv("--sans"),style:"pointer-events:none"},"得票 "+n.votes.size+"/"+MAJ));
  });
  svg.appendChild(el("text",{x:14,y:18,fill:cv("--ink-3"),"font-size":10.5,"font-family":cv("--sans")},
    "蓝点 = RequestVote　金点 = 投票回复　绿点 = 心跳　外环 = 选举计时器"));
  // 统计
  const leader=R.nodes.find(n=>n.alive&&n.state==="L");
  const maxTerm=Math.max(...R.nodes.map(n=>n.term));
  $("#st2").innerHTML=
    '<div class="stat"><div class="k">当前 Leader</div><div class="v" style="color:'+(leader?cv("--ok"):cv("--crit"))+'">'+
      (leader?"N"+(leader.id+1):"无")+'</div><div class="u">'+(leader?"term "+leader.term:"选举中")+'</div></div>'+
    '<div class="stat"><div class="k">最大 term</div><div class="v">'+maxTerm+'</div><div class="u">逻辑时钟</div></div>'+
    '<div class="stat"><div class="k">发起过的选举</div><div class="v">'+R.elections+'</div><div class="u">次</div></div>'+
    '<div class="stat"><div class="k">分裂投票</div><div class="v" style="color:'+(R.splits?cv("--warn"):cv("--ink"))+'">'+R.splits+'</div><div class="u">次</div></div>'+
    '<div class="stat"><div class="k">同一 term 的 Leader 数</div><div class="v" style="color:'+(R.violated?cv("--crit"):cv("--ok"))+'">'+
      R.maxLeadersPerTerm+'</div><div class="u">'+(R.violated?"⚠ 安全性被破坏":"✓ 选举安全性成立")+'</div></div>';
  const lg=$("#lg2");
  lg.innerHTML=R.log.slice(-40).map(x=>'<div'+(x.col?' style="color:'+cv(x.col)+'"':'')+'>'+x.m+'</div>').join("");
  lg.scrollTop=lg.scrollHeight;
}
function frame2(ts){
  if(R.run){ const dt=Math.min(ts-R.last,60); tick2(dt); }
  R.last=ts; draw2(); requestAnimationFrame(frame2);
}
$("#sv2").addEventListener("click",e=>{
  const t=e.target; if(!t.classList||!t.classList.contains("nd")) return;
  const n=R.nodes[+t.dataset.i]; n.alive=!n.alive;
  if(!n.alive){ n.state="F"; n.votes.clear(); log2("N"+(n.id+1)+" 被杀死","--crit"); }
  else { n.timer=0; n.timeout=rto(); log2("N"+(n.id+1)+" 复活"); }
});
["r2d","r2l","r2t"].forEach(id=>{const u={r2d:["l2d"," ms"],r2l:["l2l","%"],r2t:["l2t"," ms"]}[id];
  const f=()=>$("#"+u[0]).textContent=$("#"+id).value+u[1]; $("#"+id).oninput=f; f();});
$("#b2run").onclick=e=>{R.run=!R.run;e.target.textContent=R.run?"暂停":"运行 / 暂停";};
$("#b2kill").onclick=()=>{const l=R.nodes.find(n=>n.alive&&n.state==="L");
  if(l){l.alive=false;l.state="F";l.votes.clear();log2("N"+(l.id+1)+"（Leader）被杀死","--crit");}
  else log2("当前没有 Leader");};
$("#b2part").onclick=()=>{R.part=true;log2("网络分区：{N1,N2,N3} | {N4,N5}　少数派将永远选不出 Leader","--crit");};
$("#b2heal").onclick=()=>{R.part=false;R.nodes.forEach(n=>{if(!n.alive){n.alive=true;n.timer=0;n.timeout=rto();}});
  log2("分区修复，全部节点复活","--ok");};
$("#b2reset").onclick=()=>{reset2();};
reset2(); requestAnimationFrame(frame2);

/* ══════════════════════════════════════════════════════════════════
   实验 3 · 固定超时 vs 随机超时
   ══════════════════════════════════════════════════════════════════ */
function simElections(n, jitter, window_, trials){
  const BASE=600, MSG=30;   // 一次 RequestVote 单向飞行时间
  let totalRounds=0, totalTime=0, splitRounds=0;
  for(let t=0;t<trials;t++){
    let elapsed=0, rounds=0;
    for(;;){
      rounds++;
      const to=[];
      for(let i=0;i<n;i++) to.push(BASE + (Math.random()*2-1)*jitter + Math.random()*window_);
      to.sort((a,b)=>a-b);
      // 在最早者发出 RequestVote 送达之前也醒来的节点，都会给自己投票
      let cands=1;
      for(let i=1;i<n;i++) if(to[i] < to[0]+MSG) cands++;
      const votesForFirst = 1 + (n - cands);       // 自己 + 所有还没醒的节点
      elapsed += to[0] + MSG*2;
      if(votesForFirst >= Math.floor(n/2)+1){ totalRounds+=rounds; totalTime+=elapsed; break; }
      splitRounds++;
      if(rounds>60){ totalRounds+=rounds; totalTime+=elapsed; break; }
    }
  }
  return {rounds:totalRounds/trials, time:totalTime/trials, splitRate:splitRounds/(totalRounds)};
}
function draw3(){
  const n=+$("#r3n").value, j=+$("#r3j").value, w=+$("#r3w").value;
  $("#l3n").textContent=n; $("#l3j").textContent=j+" ms"; $("#l3w").textContent=w+" ms";
  const fixed=simElections(n,j,0,2000), rand=simElections(n,j,w,2000);
  const svg=$("#sv3"); svg.innerHTML="";
  const L=150,Rr=660,TOP=34,BH=30,GAP=44;
  const mx=Math.max(fixed.time,rand.time,1);
  [["固定超时（区间宽度 0）",fixed,"--crit"],["随机超时（宽度 "+w+"ms）",rand,"--ok"]].forEach((row,i)=>{
    const y=TOP+i*(BH+GAP), wpx=Math.max((row[1].time/mx)*(Rr-L),4);
    svg.appendChild(el("text",{x:L-12,y:y+BH/2+4,fill:cv("--ink-2"),"font-size":11.5,"text-anchor":"end","font-family":cv("--sans")},row[0]));
    svg.appendChild(el("rect",{x:L,y:y,width:wpx,height:BH,rx:4,fill:cv(row[2])}));
    svg.appendChild(el("text",{x:L+wpx+10,y:y+BH/2+4,fill:cv("--ink"),"font-size":11.5,"font-family":cv("--sans")},
      Math.round(row[1].time)+" ms　·　平均 "+row[1].rounds.toFixed(2)+" 轮"));
    svg.appendChild(el("text",{x:L,y:y+BH+16,fill:cv("--ink-3"),"font-size":10.5,"font-family":cv("--sans")},
      "分裂投票占比 "+(row[1].splitRate*100).toFixed(1)+"%"));
  });
  svg.appendChild(el("text",{x:Rr,y:TOP+2*(BH+GAP)+6,fill:cv("--ink-3"),"font-size":10.5,"text-anchor":"end","font-family":cv("--sans")},
    "选出 Leader 的平均耗时（越短越好）· 每组 2000 次模拟"));
  $("#st3").innerHTML=
    '<div class="stat"><div class="k">固定超时 · 平均轮数</div><div class="v" style="color:var(--crit)">'+fixed.rounds.toFixed(2)+'</div><div class="u">轮才选出 Leader</div></div>'+
    '<div class="stat"><div class="k">随机超时 · 平均轮数</div><div class="v" style="color:var(--ok)">'+rand.rounds.toFixed(2)+'</div><div class="u">轮才选出 Leader</div></div>'+
    '<div class="stat"><div class="k">耗时改善</div><div class="v">'+(fixed.time/Math.max(rand.time,1)).toFixed(1)+'×</div><div class="u">随机化带来的加速</div></div>'+
    '<div class="stat"><div class="k">固定超时分裂率</div><div class="v" style="color:var(--crit)">'+(fixed.splitRate*100).toFixed(0)+'%</div><div class="u">的选举轮次是白跑的</div></div>';
  let msg;
  if(w===0) msg='把「随机区间宽度」拖到 0 时两组完全相同 —— 现在把它拉大，看差距怎么出现。';
  else if(j===0) msg='<strong>时钟抖动为 0 是最极端的情况</strong>：固定超时下所有节点严格同时醒来，'+
    '每人只拿到自己那一票，永远凑不齐过半 —— 分裂投票率接近 100%，这就是活锁。'+
    '而随机化只用一个随机数就把它打破了。';
  else msg='真实机器总有一点时钟抖动（这里是 ±'+j+'ms），它本身就能<em>偶然</em>打破一部分对称性 —— '+
    '所以固定超时也不是必然死锁。但抖动的量级远小于消息往返时间，'+
    '<strong>大量选举仍然会撞车</strong>。随机化把"偶然"变成了"设计"。';
  $("#o3").innerHTML='<div class="note '+(w===0?"warn":"ok")+'" style="margin:0"><div class="note-h">'+
    '<span class="dot" style="background:'+(w===0?cv("--warn"):cv("--ok"))+'"></span>怎么读这两条</div>'+
    '<p style="margin-bottom:0">'+msg+'<br><br>'+
    '注意这不是"随机化让选举更快"，而是<strong>随机化让选举能够终止</strong>。'+
    'FLP 说确定性算法在异步系统里不能保证终止；Raft 加了一个随机数，就换到了一条 FLP 管不着的赛道上 —— '+
    '代价是它只保证"以概率 1 终止"，而不是"N 步内一定终止"。工程上这就够了。</p></div>';
}
["r3n","r3j","r3w"].forEach(i=>$("#"+i).oninput=draw3);
draw3();
})();
</script>
</body>
</html>
